		if err != nil {
			log.Fatal(err)
		}
		layers := 0
		if flagSet("layers") {
			layers = *attnLayers
		}
		if err := graphBench(*model, *prompt, toks, layers, *ctx, *csvPath); err != nil {
			log.Fatal(err)
		}
		return

