	tolLlamaXn = 1e-3 // worst 2.74e-04: this tensor's weights are F32 either side
	tolLlamaG  = 1e-2 // worst 4.67e-03, against 8e-05 from the CPU reference
	tolLlamaM  = 2e-2 // worst 6.53e-03
)

