            vkCmdBindPipeline(rec->cmdBuf, VK_PIPELINE_BIND_POINT_COMPUTE, p->pipeline);
            vkCmdBindDescriptorSets(rec->cmdBuf, VK_PIPELINE_BIND_POINT_COMPUTE, p->pipelineLayout, 0, 1,
