new='''// reportPhases prints where a run's wall clock went, as a share of the wall
// clock the caller measured rather than of the graph's own total — so that
// whatever the graph does not account for shows up as the gap.
//
// **The first six rows are GPU time and the last three are host time** (L7d).
// A pass is one command buffer, so a block no longer has a wall clock of its
// own; what it has is the sum of its dispatches' timestamps inside that
// command buffer, which is the same figure llama.cpp's GGML_VK_PERF_LOGGER
// reports on the other side of every comparison here. `on the GPU` is the
// whole command buffer end to end, so the difference between it and the rows
// above is what the barriers between dispatches cost, and `hand-over` is the
// wall clock the submit and the fence wait take on top of that.
func reportPhases(st llm.GraphStats, wall time.Duration) {
	ms := func(d time.Duration) float64 { return float64(d.Microseconds()) / 1000 }
	total := float64(wall.Microseconds()) / 1000
	row := func(name string, d time.Duration) {
		if d == 0 {
			return
		}
		fmt.Printf("    %-11s %8.1f ms  %5.1f%%\\n", name, ms(d), 100*ms(d)/total)
	}
	for _, r := range []struct {
		name string
		d    time.Duration
	}{
		{"hyper-conn", st.HC}, {"ple n-gram", st.PLE}, {"deltanet", st.DeltaNet},
		{"attention", st.Attn}, {"moe", st.MoE}, {"lm head", st.Head},
		{"move", st.Move},
	} {
		row(r.name, r.d)
	}
	row("= on the GPU", st.GPU)
	row("gather", st.Gather)
	row("glue", st.Glue)
	row("hand-over", wall-st.GPU-st.Gather-st.Glue)
	if st.Dispatches > 0 {
		fmt.Printf("    %d dispatches, %d command buffer(s) a pass\\n",
			st.Dispatches, (st.Dispatches+llm.MaxBatch-1)/llm.MaxBatch)
	}
}'''
